// Usage: node scripts/gen-types.mjs <bundled-schema.json> <output.ts>
// Called by scripts/generate_contracts.py. Generates contracts/models.ts from the
// bundled JSON Schema with json-schema-to-typescript.
import { readFileSync, writeFileSync } from "node:fs";
import { compile } from "json-schema-to-typescript";

const [, , input, output] = process.argv;
if (!input || !output) {
  console.error("usage: node scripts/gen-types.mjs <bundled-schema.json> <output.ts>");
  process.exit(2);
}

const schema = JSON.parse(readFileSync(input, "utf8"));
const banner = [
  "/* GENERATED by scripts/generate_contracts.py from contracts/*.schema.json.",
  " * DO NOT EDIT BY HAND. Change the schemas, then regenerate.",
  " */",
].join("\n");

const ts = await compile(schema, "TradeMindContract", {
  bannerComment: banner,
  additionalProperties: false,
  unreachableDefinitions: true,
  // -1 ignores maxItems, so bounded arrays are plain T[] instead of huge tuple unions.
  // Limits are still enforced at runtime by the JSON Schema validators.
  maxItems: -1,
  declareExternallyReferenced: true,
  format: true,
  style: { singleQuote: false, semi: true },
});

writeFileSync(output, ts.replace(/\r\n/g, "\n"), { encoding: "utf8" });
console.log(`wrote ${output}`);
